  1→//! Apply update handling for Scribe actor
  2→//!
  3→//! Handles incoming layer updates (local or remote), including permission checks,
  4→//! validation, and CRDT merge.
  5→//!
  6→//! Note: Derivation is now handled externally by kunki/LuaRuntime which
  7→//! subscribes to PageUpdate::LayerChanged events.
  8→//!
  9→//! ## Key Types
 10→//!
 11→//! - `UpdateContext`: Computed context for an incoming update - all decisions made upfront
 12→//! - `ApplyOutcome`: Result of applying an update (Applied or Rejected)
 13→
 14→use logging_utils::ShortLayer;
 15→use tracing::{debug, error, info, warn, instrument};
 16→
 17→use domains::Layer;
 18→
 19→use super::broadcast::{broadcast_update, notify_layer_discovered};
 20→use crate::layer_unit::LayerUnit;
 21→use crate::loro_observer::{set_pending_update_source, clear_pending_update_source, setup_layer_observer};
 22→use crate::message::SyncEvent;
 23→use crate::permit::{Permissions, PermitContext};
 24→use crate::state::ScribeState;
 25→use crate::JsonOp;
 26→use crate::state::normalize_layer_name;
 27→
 28→// Update Context - Centralized Decision Logic
 29→
 30→/// Context for an incoming update - computed once, used throughout
 31→///
 32→/// **Design**: All decisions about how to handle an update are computed upfront.
 33→/// This makes the apply flow clearer and easier to test.
 34→#[derive(Debug)]
 35→pub struct UpdateContext {
 36→    /// Layer being updated
 37→    pub layer_name: String,
 38→    /// Source of update: None = local, Some = remote peer (user_did, device_id)
 39→    pub from_peer: Option<(String, String)>,
 40→    /// Role of the peer (for validation) - "node", "owner", "viewer", etc.
 41→    pub peer_role: String,
 42→
 43→    /// Is this a remote update (from a peer)?
 44→    pub is_remote: bool,
 45→    /// Is this layer local-only (never synced)?
 46→    pub is_local_only: bool,
 47→    /// Does this update need Lua validation?
 48→    pub should_validate: bool,
 49→    /// Should we broadcast after applying?
 50→    pub should_broadcast: bool,
 51→    /// Is this a new layer (needs creation)?
 52→    pub is_new_layer: bool,
 53→}
 54→
 55→impl UpdateContext {
 56→    /// Create context for an incoming update
 57→    ///
 58→    /// **Context**: Computes all decisions based on state and update metadata
 59→    /// **Note**: Permission checks are done separately (may reject before context is useful)
 60→    pub fn new(
 61→        state: &ScribeState,
 62→        layer_name: &str,
 63→        from_peer: Option<(String, String)>,
 64→    ) -> Self {
 65→        let is_remote = from_peer.is_some();
 66→        let is_local_only = Permissions::is_local_only(layer_name);
 67→        let is_new_layer = !state.units.contains_key(layer_name);
 68→
 69→        // Determine peer role for validation
 70→        let peer_role = if let Some(ref peer) = from_peer {
 71→            get_peer_role(state, &peer.0)
 72→        } else {
 73→            "local".to_string()
 74→        };
 75→
 76→        // Should validate: remote update AND ValidationHandle exists
 77→        let should_validate = is_remote && state.validation_handle.is_some();
 78→
 79→        // Should broadcast: remote update (local updates use observer)
 80→        let should_broadcast = is_remote;
 81→
 82→        Self {
 83→            layer_name: layer_name.to_string(),
 84→            from_peer,
 85→            peer_role,
 86→            is_remote,
 87→            is_local_only,
 88→            should_validate,
 89→            should_broadcast,
 90→            is_new_layer,
 91→        }
 92→    }
 93→}
 94→
 95→// Apply Outcome - Event-Driven Pattern
 96→
 97→/// Outcome of applying an update
 98→///
 99→/// **Design**: Separates the "what happened" from "what to do next"
100→/// This enables cleaner outcome handling and better error messages
101→#[derive(Debug)]
102→pub enum ApplyOutcome {
103→    /// Update was successfully applied
104→    Applied {
105→        /// Layer that was updated
106→        layer_name: String,
107→        /// Ops extracted from update (for derivation)
108→        ops: Vec<JsonOp>,
109→        /// Was a new layer created?
110→        created_layer: bool,
111→    },
112→    /// Update was rejected
113→    Rejected {
114→        /// Reason for rejection
115→        reason: String,
116→    },
117→}
118→
119→// Apply Update Handler
120→
121→/// Handle layer update (local or remote)
122→///
123→/// **Context**: Edit from UI or sync push from peer
124→/// **We do**: Permission check, validation, CRDT merge
125→/// **Broadcast**: Handled automatically by Loro observer (set up at startup)
126→/// **Returns**: Ok(()) on success, Err(message) on failure
127→#[instrument(skip(state, update, permit), fields(page_id = %state.page_id, layer = %ShortLayer(layer_name)))]
128→pub async fn handle_apply_update(
129→    state: &mut ScribeState,
130→    layer_name: &str,
131→    update: &[u8],
132→    from_peer: Option<(String, String)>,
133→    permit: Option<&str>,
134→) -> std::result::Result<(), String> {
135→    let _ = permit; // Permit is used for subscription in Courier, not here
136→
137→    // Defense-in-depth: normalize layer name (strip page_id/ prefix)
138→    let layer_name = normalize_layer_name(layer_name, &state.page_id);
139→    let layer_name = layer_name.as_str();
140→
141→    // Build context - computes all decisions upfront
142→    let ctx = UpdateContext::new(state, layer_name, from_peer.clone());
143→
144→    // Step 1: Apply the update (with permission checks, validation, CRDT merge)
145→    let outcome = apply_update_core(state, &ctx, update).await;
146→
147→    // Step 2: Handle the outcome
148→    let from_peer_did = ctx.from_peer.as_ref().map(|(d, _)| d.as_str());
149→    match outcome {
150→        ApplyOutcome::Applied { layer_name, ops: _, created_layer } => {
151→            // Mark layer as dirty for persistence
152→            if let Some(unit) = state.units.get_mut(&layer_name) {
153→                unit.mark_dirty();
154→            }
155→            debug!(layer = %layer_name, created = created_layer, "Update applied successfully");
156→            state.emit_apply_update_capture(&layer_name, from_peer_did, "applied", None);
157→
158→            // Post-apply handling for remote updates
159→            if ctx.is_remote {
160→                handle_post_apply(state, &layer_name, ctx.from_peer.clone()).await;
161→            }
162→
163→            // Ensure sender is a per-layer subscriber on this LayerUnit.
164→            // This handles the case where the LayerUnit was created (e.g. via
165→            // LayerSubscribeAck) before the sender's data arrived. Without this,
166→            // the sender would never receive broadcasts for this layer.
167→            ensure_sender_subscribed(state, &layer_name, ctx.from_peer.as_ref());
168→
169→            // Node-side: detect new dynamic layers in creator's __sync_meta
170→            // Instead of doing fanout directly, emit SyncEvent::SubscribeLayers
171→            // so the node sends LayerSubscribe to the creator to get authority.
172→            if ctx.is_remote {
173→                use super::sync_meta;
174→                if sync_meta::is_sync_meta_layer(&layer_name) {
175→                    if let Some(creator_did) = sync_meta::extract_peer_did(&layer_name) {
176→                        let creator_did = creator_did.to_string();
177→                        let new_layers = sync_meta::detect_new_dynamic_layers(state, &creator_did);
178→                        if !new_layers.is_empty() {
179→                            if let Some(ref tx) = state.sync_event_tx {
180→                                let _ = tx.try_send(SyncEvent::SubscribeLayers {
181→                                    page_id: state.page_id.clone(),
182→                                    creator_did: creator_did.to_string(),
183→                                    layers: new_layers,
184→                                });
185→                            }
186→                        }
187→                    }
188→                }
189→            }
190→
191→            // Update sender's vector
192→            if let Some(ref peer) = ctx.from_peer {
193→                update_sender_vector(state, peer, &layer_name);
194→            }
195→
196→            // Broadcast to eligible subscribers
197→            if ctx.should_broadcast {
198→                broadcast_update(state, &layer_name, ctx.from_peer.as_ref()).await;
199→            }
200→
201→            // Note: Derivation is now handled externally by kunki/LuaRuntime
202→            // which subscribes to PageUpdate::LayerChanged events
203→
204→            Ok(())
205→        }
206→        ApplyOutcome::Rejected { reason } => {
207→            warn!(layer = %layer_name, reason = %reason, "Update rejected");
208→            state.emit_apply_update_capture(layer_name, from_peer_did, "rejected", Some(&reason));
209→            Err(reason)
210→        }
211→    }
212→}
213→
214→/// Core apply logic - returns ApplyOutcome
215→///
216→/// **Context**: Separated from handle_apply_update for cleaner testing
217→/// **Returns**: ApplyOutcome::Applied or ApplyOutcome::Rejected
218→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %ctx.layer_name))]
219→async fn apply_update_core(
220→    state: &mut ScribeState,
221→    ctx: &UpdateContext,
222→    update: &[u8],
223→) -> ApplyOutcome {
224→    // Step 1: Permission check - reject local_only layers from remote
225→    if ctx.is_remote && ctx.is_local_only {
226→        return ApplyOutcome::Rejected {
227→            reason: "local_only layer cannot be updated by remote peer".to_string(),
228→        };
229→    }
230→
231→    // Step 2: Permission check for remote updates
232→    if let Some(ref peer) = ctx.from_peer {
233→        if !Permissions::can_write(state, peer, &ctx.layer_name) {
234→            return ApplyOutcome::Rejected {
235→                reason: "Permission denied: cannot write to layer".to_string(),
236→            };
237→        }
238→    }
239→
240→    // Step 3: Extract ops for validation (using optimized pre-commit method)
241→    let extracted_ops = if ctx.should_validate {
242→        // Use Layer::extract_ops_from_bytes (5-10x faster than old fork+diff)
243→        match Layer::extract_ops_from_bytes(update) {
244→            Ok(ops) => Some(ops),
245→            Err(e) => {
246→                // Log extraction failure - validation will proceed with empty ops
247→                // This could mask invalid updates, so log at warn level
248→                warn!(layer = %ctx.layer_name, error = %e, "Failed to extract ops from update, proceeding with empty ops");
249→                None
250→            }
251→        }
252→    } else {
253→        None
254→    };
255→
256→    // Step 4: Validate with Lua (if needed)
257→    if ctx.should_validate {
258→        if let Err(e) = validate_update_with_context(state, ctx, &extracted_ops).await {
259→            return ApplyOutcome::Rejected { reason: e };
260→        }
261→    }
262→
263→    // Step 5: Create layer if needed (remote only)
264→    let created_layer = if ctx.is_new_layer {
265→        if ctx.is_remote {
266→            create_layer_from_peer(state, &ctx.layer_name);
267→            true
268→        } else {
269→            return ApplyOutcome::Rejected {
270→                reason: "Layer not found".to_string(),
271→            };
272→        }
273→    } else {
274→        false
275→    };
276→
277→    // Step 6: Apply CRDT update
278→    if let Err(e) = apply_crdt_update(state, &ctx.layer_name, update, ctx.from_peer.clone()) {
279→        return ApplyOutcome::Rejected { reason: e };
280→    }
281→
282→    ApplyOutcome::Applied {
283→        layer_name: ctx.layer_name.clone(),
284→        ops: extracted_ops.unwrap_or_default(),
285→        created_layer,
286→    }
287→}
288→
289→// Helper Functions
290→
291→/// Validate update using ValidationHandle (kunki) or fallback to Lua runtime
292→///
293→/// **Context**: Business logic validation for remote updates
294→/// **Returns**: Ok(()) if validation passed, Err(message) if rejected
295→/// **Timeout**: 5 seconds for ValidationHandle (kunki), immediate for Lua runtime
296→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %ctx.layer_name))]
297→async fn validate_update_with_context(
298→    state: &ScribeState,
299→    ctx: &UpdateContext,
300→    extracted_ops: &Option<Vec<JsonOp>>,
301→) -> Result<(), String> {
302→    let Some(ref ops) = extracted_ops else {
303→        return Ok(()); // No ops to validate
304→    };
305→
306→    if ops.is_empty() {
307→        return Ok(()); // Empty ops = nothing to validate
308→    }
309→
310→    // Extract actual DID from from_peer, not the role
311→    let from_did = ctx.from_peer.as_ref().map(|(d, _)| d.as_str()).unwrap_or("local");
312→
313→    // Use ValidationHandle (kunki mode with presence_lib)
314→    let Some(ref validation_handle) = state.validation_handle else {
315→        // No validation available - allow update (viewer/owner mode without kunki)
316→        // This is expected in viewer/owner mode but unexpected in node mode without kunki
317→        warn!(layer = %ctx.layer_name, from_did = %from_did, "No ValidationHandle available, allowing remote update without validation");
318→        return Ok(());
319→    };
320→
321→    use tokio::time::{timeout, Duration};
322→
323→    let validation_future = validation_handle.validate_ops(
324→        &state.page_id,
325→        &ctx.layer_name,
326→        ops,
327→        from_did,
328→        &ctx.peer_role,
329→    );
330→
331→    match timeout(Duration::from_secs(5), validation_future).await {
332→        Ok(Ok((true, _))) => {
333→            debug!(layer = %ctx.layer_name, from_did = %from_did, role = %ctx.peer_role, "Validation passed");
334→            Ok(())
335→        }
336→        Ok(Ok((false, error_msg))) => {
337→            let msg = error_msg.unwrap_or_else(|| "Validation failed".to_string());
338→            warn!(layer = %ctx.layer_name, from_did = %from_did, role = %ctx.peer_role, error = %msg, "Validation rejected update");
339→            Err(format!("Validation failed: {}", msg))
340→        }
341→        Ok(Err(e)) => {
342→            warn!(layer = %ctx.layer_name, error = %e, "Validation error, rejecting update");
343→            Err(format!("Validation error: {}", e))
344→        }
345→        Err(_) => {
346→            warn!(layer = %ctx.layer_name, "Validation timeout (5s), rejecting update");
347→            Err("Validation timeout".to_string())
348→        }
349→    }
350→}
351→
352→/// Create a new layer from peer sync
353→///
354→/// **Context**: Peer sent update for a layer we don't have yet
355→/// **We do**: Create layer, set up observer, notify UI
356→#[instrument(skip(state), fields(page_id = %state.page_id))]
357→fn create_layer_from_peer(state: &mut ScribeState, layer_name: &str) {
358→    // Defense-in-depth: normalize layer name (strip page_id/ prefix)
359→    let layer_name = normalize_layer_name(layer_name, &state.page_id);
360→    let layer_name = layer_name.as_str();
361→    let mut unit = LayerUnit::new_empty();
362→    unit.set_local_only(!state.should_sync_layer(layer_name));
363→    unit.mark_dirty();
364→    state.units.insert(layer_name.to_string(), unit);
365→    info!(layer = %layer_name, "Created new layer from peer sync");
366→
367→    // Add existing subscribers to this new layer
368→    if let Ok(subs) = state.subscribers.read() {
369→        for ((did, _), info) in subs.iter() {
370→            if info.can_receive_layer(layer_name, &state.page_id) {
371→                if let Some(unit) = state.units.get(layer_name) {
372→                    let can_write = info.can_write_layer(layer_name, &state.page_id);
373→                    let caps = crate::layer_unit::Capabilities { read: true, write: can_write, sync: true };
374→                    unit.add_subscriber(did.clone(), caps, info.broadcast_tx.clone());
375→                    state.emit_layer_auth_capture(layer_name, did, "subscriber_added_from_peer");
376→                }
377→            }
378→        }
379→    }
380→
381→    // Set up Loro observer for new layer to enable sync broadcasts
382→    setup_layer_observer(state, layer_name);
383→
384→    // Notify UI subscribers about the new layer
385→    notify_layer_discovered(state, layer_name);
386→}
387→
388→/// Apply CRDT update to layer
389→///
390→/// **Context**: Actually merge the update into the layer
391→/// **We do**: Set pending source, apply, clear pending source
392→#[instrument(skip(state, update), fields(page_id = %state.page_id, layer = %layer_name))]
393→fn apply_crdt_update(
394→    state: &mut ScribeState,
395→    layer_name: &str,
396→    update: &[u8],
397→    from_peer: Option<(String, String)>,
398→) -> Result<(), String> {
399→    // Set pending update source BEFORE apply() so observer knows who caused this change
400→    set_pending_update_source(state, from_peer);
401→
402→    // Get the layer and apply update
403→    let result = if let Some(unit) = state.units.get(layer_name) {
404→        unit.layer().apply(update)
405→    } else {
406→        clear_pending_update_source(state);
407→        return Err("Layer not found".to_string());
408→    };
409→
410→    if let Err(e) = result {
411→        // Clear on error too
412→        clear_pending_update_source(state);
413→        error!(error = %e, "Failed to apply update to layer");
414→        return Err(format!("Failed to apply update: {}", e));
415→    }
416→
417→    // Clear pending update source AFTER apply() (observer already captured it)
418→    clear_pending_update_source(state);
419→
420→    Ok(())
421→}
422→
423→/// Handle post-apply actions for remote updates
424→///
425→/// **Context**: Remote update was successfully applied
426→/// **We do**: Flush app layers immediately
427→/// **Note**: UI notification is handled by Loro observer (no duplicate emit here)
428→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
429→async fn handle_post_apply(
430→    state: &mut ScribeState,
431→    layer_name: &str,
432→    _from_peer: Option<(String, String)>,
433→) {
434→    // For app layers, flush immediately to storage so restart loads new code
435→    if layer_name.starts_with("app:") {
436→        if let Some(unit) = state.units.get_mut(layer_name) {
437→            let snapshot = unit.layer().export_snapshot();
438→            if let Err(e) = state.layer_storage.save_layer(layer_name, &snapshot) {
439→                error!(layer = %layer_name, error = %e, "Failed to save app layer immediately");
440→            } else {
441→                info!(layer = %layer_name, "Saved app layer immediately for restart");
442→                // Remove from dirty since we just saved it
443→                unit.clear_dirty();
444→            }
445→        }
446→    }
447→
448→    // Note: UI notification via emit_layer_changed_after_apply was removed
449→    // The Loro observer handles PageUpdate::LayerChanged for all changes (local and remote)
450→    // This prevents duplicate notifications
451→}
452→
453→/// Update sender's peer vector after receiving their update
454→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
455→fn update_sender_vector(state: &mut ScribeState, peer: &(String, String), layer_name: &str) {
456→    if let Some(unit) = state.units.get(layer_name) {
457→        if let Ok(mut subs) = state.subscribers.write() {
458→            if let Some(info) = subs.get_mut(peer) {
459→                let current_vector = unit.layer().version_vector();
460→                info.vectors.insert(layer_name.to_string(), current_vector);
461→                debug!(user_did = %peer.0, "Updated sender's peer vector");
462→            }
463→        }
464→    }
465→}
466→
467→/// Ensure the update sender is a per-layer subscriber on the LayerUnit.
468→///
469→/// **Context**: When a LayerUnit is created via LayerSubscribeAck before the
470→/// creator's data arrives, the creator isn't in the per-layer subscriber list.
471→/// This adds them if they're a global subscriber with access to this layer.
472→fn ensure_sender_subscribed(
473→    state: &ScribeState,
474→    layer_name: &str,
475→    from_peer: Option<&(String, String)>,
476→) {
477→    let Some(peer) = from_peer else { return };
478→    let (peer_did, _device_id) = peer;
479→
480→    // Check if already subscribed at the layer level
481→    if let Some(unit) = state.units.get(layer_name) {
482→        if unit.can_push_to(peer_did) {
483→            return;
484→        }
485→    }
486→
487→    // Look up in global subscribers
488→    if let Ok(subs) = state.subscribers.read() {
489→        if let Some(info) = subs.get(peer) {
490→            if info.can_receive_layer(layer_name, &state.page_id) {
491→                if let Some(unit) = state.units.get(layer_name) {
492→                    let can_write = info.can_write_layer(layer_name, &state.page_id);
493→                    let caps = crate::layer_unit::Capabilities {
494→                        read: true,
495→                        write: can_write,
496→                        sync: true,
497→                    };
498→                    unit.add_subscriber(peer_did.clone(), caps, info.broadcast_tx.clone());
499→                    state.emit_layer_auth_capture(
500→                        layer_name, peer_did, "sender_added_post_apply",
501→                    );
502→                }
503→            }
504→        }
505→    }
506→}
507→
508→/// Get role for a peer from their stored permit
509→///
510→/// **Context**: Determining role for Lua validation
511→/// **Checks**:
512→/// 1. Sync target (owner/viewer mode) -> our role's counterpart
513→/// 2. Stored permit (node mode) -> extract role from permit
514→/// 3. Default -> "peer"
515→#[instrument(skip(state), fields(page_id = %state.page_id))]
516→fn get_peer_role(state: &ScribeState, peer_did: &str) -> String {
517→    // If peer is our sync target, they are the "node" from our perspective
518→    if let Some(ref config) = state.sync_config {
519→        if let Some(ref sync_target) = config.sync_target {
520→            if sync_target == peer_did {
521→                return "node".to_string();
522→            }
523→        }
524→    }
525→
526→    // Node mode: look up peer's stored permit and extract role via PermitContext
527→    if let Some(ref resolver) = state.peer_resolver {
528→        if let Some(permit_token) = resolver.load_user_permit(peer_did) {
529→            let role = PermitContext::from_token(&permit_token, &state.page_id, peer_did)
530→                .map(|ctx| ctx.permit().relationship().unwrap_or("peer").to_string())
531→                .unwrap_or_else(|_| "peer".to_string());
532→            debug!(peer_did = %peer_did, role = %role, "Got peer role from stored permit via PermitContext");
533→            return role;
534→        }
535→    }
536→
537→    // Default role
538→    "peer".to_string()
539→}
540→

