file.content:
    padding: 4px;
    spacing: 2px;

    for member in AppAPI.member_picker: Rectangle {
        height: 32px;
        background: member-touch.has-hover ? Theme.bg-hover : transparent;
        border-radius: 4px;

        member-touch := TouchArea {
            clicked => {
                AppAPI.on_click("toggle_member:" + member.did + ":" + member.name);
            }
        }

        HorizontalLayout {
            padding-left: 10px;
            padding-right: 10px;
            spacing: 8px;

            // Checkbox
            Rectangle {
                width: 16px;
                height: 16px;
                background: member.is_selected ? Theme.green-online : transparent;
                border-radius: 3px;
                border-width: 1px;
                border-color: member.is_selected ? Theme.green-online : Theme.text-secondary;
                y: (parent.height - self.height) / 2;

                if member.is_selected: Text {
                    text: "✓";
                    font-size: 11px;
                    color: white;
                    horizontal-alignment: center;
                    vertical-alignment: center;
                }
            }

            Text {
                text: member.name;
                font-size: 13px;
                color: Theme.text-primary;
                vertical-alignment: center;
                overflow: elide;
            }
        }
    }

    if AppAPI.member_picker.length == 0: Rectangle {
        height: 60px;

        Text {
            text: "No other users online";
            font-size: 13px;
            color: Theme.text-secondary;
            horizontal-alignment: center;
            vertical-alignment: center;
        }
    }
}

