1001→    /// Handle layer discovered
1002→    ///
1003→    /// **Context**: New layer arriving via sync (e.g., derived/orders_summary first appearance)
1004→    /// **We do**: Process bindings for the discovered layer, then call Lua callback
1005→    /// **Why**: Without binding processing here, first-time layer arrivals are invisible to UI
1006→    fn handle_layer_discovered(&self, layer_name: &str) -> Result<(), String> {
1007→        // Process bindings for the discovered layer (fetches full data from Scribe)
1008→        if self.ui_enabled {
1009→            let has_bindings = {
1010→                let manager = self.binding_manager.lock();
1011→                !manager.get_bindings_for_layer(layer_name).is_empty()
1012→            };
1013→
1014→            if has_bindings {
1015→                if let Ok(data) = self.fetch_layer_data(layer_name) {
1016→                    self.process_bindings(layer_name, Some(&data), None);
1017→                }
1018→            }
1019→        }
1020→
1021→        if self.handler_cache.on_layer_discovered {
1022→            let func: Function = self.lua.globals().get("on_layer_discovered").unwrap();
1023→            if let Err(e) = func.call::<()>(layer_name.to_string()) {
1024→                warn!(page_id = %self.page_id, layer = %layer_name, error = %e, "on_layer_discovered error");
1025→            }
1026→        }
1027→
1028→        self.trigger_derivation(layer_name);
1029→
1030→        Ok(())
1031→    }
