1187→                    }
1188→                }
1189→            }
1190→            UiEventType::TextChanged { element: _, text } => {
1191→                if self.handler_cache.on_text_input {
1192→                    let func: Function = self.lua.globals().get("on_text_input").unwrap();
1193→                    if let Err(e) = func.call::<()>(text) {
