1195→                    }
1196→                }
1197→            }
1198→            UiEventType::Custom { name, data } => {
1199→                // Dispatch to event bus
1200→                let event = crate::event_bus::Event::new(&name, crate::event_bus::EventSource::Human)
1201→                    .with_data(data);
1202→
1203→                let deliveries = self.ui_shared.lock().event_bus.emit(event);
1204→                for (subscriber_id, _callback_key, delivery) in deliveries {
1205→                    self.dispatch_event_delivery(subscriber_id, delivery);
1206→                }
1207→            }
1208→            _ => {}
1209→        }
1210→        Ok(())
1211→    }
