1415→    /// Check if a function exists
1416→    pub fn has_function(&self, name: &str) -> bool {
1417→        self.lua.globals()
1418→            .get::<Value>(name)
1419→            .map(|v| matches!(v, Value::Function(_)))
1420→            .unwrap_or(false)
1421→    }
1422→
1423→    /// Validate operations
1424→    pub fn validate_ops(
1425→        &self,
1426→        layer_name: &str,
1427→        ops: &[serde_json::Value],
1428→        from_did: &str,
1429→        role: &str,
1430→    ) -> Result<(bool, Option<String>), String> {
1431→        let globals = self.lua.globals();
1432→
1433→        let validate_fn: Function = match globals.get("validate_ops") {
1434→            Ok(f) => f,
1435→            Err(_) => {
1436→                return Ok((true, None));
1437→            }
1438→        };
1439→
1440→        let ops_table = self.lua.create_table()
1441→            .map_err(|e| format!("Failed to create ops table: {}", e))?;
1442→
1443→        for (i, op_json) in ops.iter().enumerate() {
1444→            let op_lua = json_to_lua(&self.lua, op_json)
1445→                .map_err(|e| format!("Failed to convert op to Lua: {}", e))?;
1446→            ops_table.set(i + 1, op_lua)
1447→                .map_err(|e| format!("Failed to add op to table: {}", e))?;
1448→        }
1449→
1450→        let result: bool = validate_fn.call((
1451→            layer_name,
1452→            ops_table,
1453→            from_did,
1454→            role,
1455→            self.page_id.as_str(),
1456→        )).map_err(|e| format!("validate_ops error: {}", e))?;
1457→
1458→        Ok((result, if result { None } else { Some("Validation failed".to_string()) }))
1459→    }
1460→}
