  1→//! Slint VecModel FFI Bindings for Lua
  2→//!
  3→//! Provides direct access to Slint VecModel for fine-grained UI updates.
  4→//! Lua receives model handles (Rc pointers), not data copies.
  5→//!
  6→//! **Pattern**: Mirrors loro_bindings.rs - Lua gets lightweight handles
  7→//! **Memory**: Just an Rc pointer (shared with Slint, no copy)
  8→//! **Operations**: Directly mutate the model, triggering ModelNotify
  9→
 10→use slint::{VecModel, Model};
 11→use slint_interpreter::Value as SlintValue;
 12→use mlua::{UserData, UserDataMethods, Value as LuaValue, Error as LuaError};
 13→use std::rc::Rc;
 14→
 15→/// Lua wrapper for Slint VecModel
 16→///
 17→/// **Memory**: Just an Rc pointer (shared with Slint, no copy)
 18→/// **Operations**: Directly mutate the model, triggering ModelNotify
 19→pub struct LuaSlintModel {
 20→    model: Rc<VecModel<SlintValue>>,
 21→    property_name: String,  // For debugging/logging
 22→}
 23→
 24→impl LuaSlintModel {
 25→    pub fn new(model: Rc<VecModel<SlintValue>>, property_name: String) -> Self {
 26→        Self { model, property_name }
 27→    }
 28→}
 29→
 30→impl UserData for LuaSlintModel {
 31→    fn add_methods<M: UserDataMethods<Self>>(methods: &mut M) {
 32→        // model:len() - Get row count
 33→        methods.add_method("len", |_, this, ()| {
 34→            Ok(this.model.row_count())
 35→        });
 36→
 37→        // model:push(item) - Append item to end
 38→        // Automatically triggers ModelNotify::row_added()
 39→        methods.add_method("push", |lua, this, item: LuaValue| {
 40→            let slint_val = lua_to_slint_value(lua, &item)?;
 41→            this.model.push(slint_val);
 42→            tracing::debug!(
 43→                property = %this.property_name,
 44→                "VecModel::push triggered (UI will update row)"
 45→            );
 46→            Ok(())
 47→        });
 48→
 49→        // model:insert(index, item) - Insert at position
 50→        // Automatically triggers ModelNotify::row_added(index)
 51→        methods.add_method("insert", |lua, this, (index, item): (usize, LuaValue)| {
 52→            let slint_val = lua_to_slint_value(lua, &item)?;
 53→            this.model.insert(index, slint_val);
 54→            tracing::debug!(
 55→                property = %this.property_name,
 56→                index = index,
 57→                "VecModel::insert triggered"
 58→            );
 59→            Ok(())
 60→        });
 61→
 62→        // model:remove(index) - Remove item at index
 63→        // Automatically triggers ModelNotify::row_removed(index)
 64→        methods.add_method("remove", |_, this, index: usize| {
 65→            if index < this.model.row_count() {
 66→                this.model.remove(index);
 67→                tracing::debug!(
 68→                    property = %this.property_name,
 69→                    index = index,
 70→                    "VecModel::remove triggered"
 71→                );
 72→                Ok(())
 73→            } else {
 74→                Err(LuaError::RuntimeError(format!(
 75→                    "Index {} out of bounds (len={})",
 76→                    index,
 77→                    this.model.row_count()
 78→                )))
 79→            }
 80→        });
 81→
 82→        // model:get(index) - Get item at index (read-only access)
 83→        methods.add_method("get", |lua, this, index: usize| {
 84→            match this.model.row_data(index) {
 85→                Some(val) => slint_to_lua_value(lua, &val),
 86→                None => Ok(LuaValue::Nil),
 87→            }
 88→        });
 89→
 90→        // model:set(index, item) - Update item at index
 91→        // Triggers ModelNotify::row_changed(index)
 92→        methods.add_method("set", |lua, this, (index, item): (usize, LuaValue)| {
 93→            if index < this.model.row_count() {
 94→                let slint_val = lua_to_slint_value(lua, &item)?;
 95→                this.model.set_row_data(index, slint_val);
 96→                tracing::debug!(
 97→                    property = %this.property_name,
 98→                    index = index,
 99→                    "VecModel::set_row_data triggered"
100→                );
101→                Ok(())
102→            } else {
103→                Err(LuaError::RuntimeError(format!(
104→                    "Index {} out of bounds (len={})",
105→                    index,
106→                    this.model.row_count()
107→                )))
108→            }
109→        });
110→
111→        // model:clear() - Remove all items
112→        methods.add_method("clear", |_, this, ()| {
113→            this.model.set_vec(vec![]);
114→            tracing::debug!(
115→                property = %this.property_name,
116→                "VecModel::clear triggered"
117→            );
118→            Ok(())
119→        });
120→    }
121→}
122→
123→/// Convert Lua value to Slint value
124→fn lua_to_slint_value(lua: &mlua::Lua, value: &LuaValue) -> Result<SlintValue, LuaError> {
125→    use slint_interpreter::Value;
126→
127→    match value {
128→        LuaValue::Nil => Ok(Value::Void),
129→        LuaValue::Boolean(b) => Ok(Value::Bool(*b)),
130→        LuaValue::Integer(i) => Ok(Value::Number(*i as f64)),
131→        LuaValue::Number(f) => Ok(Value::Number(*f)),
132→        LuaValue::String(s) => {
133→            // BorrowedBytes implements AsRef<[u8]>
134→            let borrowed_bytes = s.as_bytes();
135→            let bytes: &[u8] = borrowed_bytes.as_ref();
136→            let str_val = std::str::from_utf8(bytes)
137→                .map_err(|e| LuaError::RuntimeError(format!("Invalid UTF-8: {}", e)))?;
138→            Ok(Value::String(slint::SharedString::from(str_val)))
139→        }
140→        LuaValue::Table(table) => {
141→            // Check if it's an array (sequential integer keys starting from 1)
142→            let mut is_array = true;
143→            let mut max_index = 0;
144→
145→            for pair in table.clone().pairs::<LuaValue, LuaValue>() {
146→                let (key, _) = pair?;
147→                match key {
148→                    LuaValue::Integer(i) if i > 0 => {
149→                        max_index = max_index.max(i as usize);
150→                    }
151→                    _ => {
152→                        is_array = false;
153→                        break;
154→                    }
155→                }
156→            }
157→
158→            if is_array && max_index > 0 {
159→                // Convert as array - create Slint Model
160→                let mut items = Vec::with_capacity(max_index);
161→                for i in 1..=max_index {
162→                    let val: LuaValue = table.get(i)?;
163→                    items.push(lua_to_slint_value(lua, &val)?);
164→                }
165→                Ok(Value::Model(std::rc::Rc::new(slint::VecModel::from(items)).into()))
166→            } else {
167→                // Convert as struct (Slint object)
168→                let mut fields = Vec::new();
169→                for pair in table.clone().pairs::<String, LuaValue>() {
170→                    let (key, val) = pair?;
171→                    let slint_val = lua_to_slint_value(lua, &val)?;
172→                    fields.push((key, slint_val));
173→                }
174→                Ok(Value::Struct(
175→                    slint_interpreter::Struct::from_iter(fields).into()
176→                ))
177→            }
178→        }
179→        _ => Err(LuaError::RuntimeError(format!(
180→            "Unsupported Lua type for Slint conversion: {:?}",
181→            value
182→        ))),
183→    }
184→}
185→
186→/// Convert Slint value to Lua value
187→fn slint_to_lua_value(lua: &mlua::Lua, value: &SlintValue) -> Result<LuaValue, LuaError> {
188→    use slint_interpreter::Value;
189→
190→    match value {
191→        Value::Void => Ok(LuaValue::Nil),
192→        Value::Bool(b) => Ok(LuaValue::Boolean(*b)),
193→        Value::Number(n) => Ok(LuaValue::Number(*n)),
194→        Value::String(s) => Ok(LuaValue::String(lua.create_string(s.as_str())?)),
195→        Value::Struct(s) => {
196→            // Convert Slint struct to Lua table
197→            let table = lua.create_table()?;
198→            // Iterate over the struct fields directly
199→            for field in s.iter() {
200→                let lua_val = slint_to_lua_value(lua, &field.1)?;
201→                // Use to_string() instead of unstable as_str()
202→                table.set(field.0.to_string(), lua_val)?;
203→            }
204→            Ok(LuaValue::Table(table))
205→        }
206→        Value::Model(_) => {
207→            // Model references - return nil for now
208→            // (Models should be accessed via ui.models, not queried)
209→            tracing::warn!("Attempted to convert Model to Lua (not supported)");
210→            Ok(LuaValue::Nil)
211→        }
212→        Value::Brush(_) | Value::Image(_) => {
213→            // UI-specific types - not used in app logic
214→            Ok(LuaValue::Nil)
215→        }
216→        _ => {
217→            // Catch-all for any new Slint value types
218→            tracing::warn!("Unknown Slint value type, returning nil");
219→            Ok(LuaValue::Nil)
220→        }
221→    }
222→}
