  1→//! Page Runtime - Generate browser shell that wraps app components
  2→//!
  3→//! Apps are pure components (no Window inheritance) with an `export global AppAPI`
  4→//! that defines their public interface. The shell wraps the app in a Window with
  5→//! tab bar. Runtime accesses app via global API (set_global_callback, set_global_property).
  6→
  7→use std::path::Path;
  8→
  9→/// App tab information
 10→#[derive(Clone, Debug)]
 11→pub struct AppTab {
 12→    pub name: String,
 13→    pub display_name: String,
 14→}
 15→
 16→/// Parsed exported types from app.slint
 17→#[derive(Default)]
 18→pub struct ExportedTypes {
 19→    /// Struct names (e.g., Product, Order)
 20→    pub structs: Vec<String>,
 21→    /// Global names (e.g., AppAPI)
 22→    pub globals: Vec<String>,
 23→}
 24→
 25→/// Parse exported types (structs and globals) from app.slint source
 26→///
 27→/// Looks for lines like: `export struct Product {` or `export global AppAPI {`
 28→pub fn parse_exported_types(slint_source: &str) -> ExportedTypes {
 29→    let mut result = ExportedTypes::default();
 30→
 31→    for line in slint_source.lines() {
 32→        let trimmed = line.trim();
 33→
 34→        // Parse: export struct Name {
 35→        if trimmed.starts_with("export struct ") {
 36→            if let Some(rest) = trimmed.strip_prefix("export struct ") {
 37→                let name = rest
 38→                    .split(|c: char| c == '{' || c.is_whitespace())
 39→                    .next()
 40→                    .unwrap_or("")
 41→                    .trim()
 42→                    .to_string();
 43→                if !name.is_empty() {
 44→                    result.structs.push(name);
 45→                }
 46→            }
 47→        }
 48→
 49→        // Parse: export global Name {
 50→        if trimmed.starts_with("export global ") {
 51→            if let Some(rest) = trimmed.strip_prefix("export global ") {
 52→                let name = rest
 53→                    .split(|c: char| c == '{' || c.is_whitespace())
 54→                    .next()
 55→                    .unwrap_or("")
 56→                    .trim()
 57→                    .to_string();
 58→                if !name.is_empty() {
 59→                    result.globals.push(name);
 60→                }
 61→            }
 62→        }
 63→    }
 64→
 65→    result
 66→}
