 68→/// Generate browser shell that imports and wraps the app
 69→///
 70→/// **Architecture:**
 71→/// - App = pure component with `export global AppAPI` for public interface
 72→/// - Shell = Window + TabBar + imports App
 73→/// - Runtime accesses app via globals (no forwarding needed)
 74→/// - Shell re-exports globals so interpreter can access them
 75→///
 76→/// **Returns:** Slint source for the shell
 77→pub fn generate_page_shell(
 78→    app_slint_path: &Path,
 79→    tabs: &[AppTab],
 80→    current_app: &str,
 81→    page_name: &str,
 82→    version: Option<&str>,
 83→) -> String {
 84→    // Read app source to parse exported types
 85→    let app_source = std::fs::read_to_string(app_slint_path).unwrap_or_default();
 86→    let exported_types = parse_exported_types(&app_source);
 87→
 88→    let app_path = app_slint_path.to_string_lossy();
 89→    let tab_bar = generate_tab_bar(tabs, current_app);
 90→
 91→    // Build import statement with App, structs, and globals
 92→    let mut imports = vec!["App as UserApp".to_string()];
 93→    imports.extend(exported_types.structs.iter().cloned());
 94→    imports.extend(exported_types.globals.iter().cloned());
 95→    let import_list = imports.join(", ");
 96→
 97→    // Re-export globals so interpreter can access them via set_global_callback
 98→    let global_exports = if exported_types.globals.is_empty() {
 99→        String::new()
100→    } else {
101→        format!("\nexport {{ {} }}", exported_types.globals.join(", "))
102→    };
103→
104→    // Generate version footer if version is provided
105→    let version_footer = if let Some(v) = version {
106→        format!(
107→            r#"
108→        // Version footer
109→        Rectangle {{
110→            height: 20px;
111→            background: #0d0d1a;
112→
113→            Text {{
114→                text: "v{version}";
115→                color: #555;
116→                font-size: 10px;
117→                horizontal-alignment: right;
118→                vertical-alignment: center;
119→                x: parent.width - self.width - 10px;
120→            }}
121→        }}"#,
122→            version = v
123→        )
124→    } else {
125→        String::new()
126→    };
127→
128→    format!(
129→        r#"import {{ VerticalBox, HorizontalBox, Button }} from "std-widgets.slint";
130→import {{ {import_list} }} from "{app_path}";
131→{global_exports}
132→
133→export component App inherits Window {{
134→    title: "{page_name}";
135→    background: #1a1a2e;
136→    preferred-width: 1024px;
137→    preferred-height: 768px;
138→    min-width: 800px;
139→    min-height: 600px;
140→
141→    // Tab callbacks (handled by Rust)
142→    callback select-tab(string);
143→    callback add-app();
144→
145→    VerticalLayout {{
146→{tab_bar}
147→
148→        // App content - no forwarding needed, runtime uses AppAPI global
149→        UserApp {{
150→            width: 100%;
151→            vertical-stretch: 1;
152→        }}
153→{version_footer}
154→    }}
155→}}"#,
156→        import_list = import_list,
157→        app_path = app_path,
158→        global_exports = global_exports,
159→        page_name = page_name,
160→        tab_bar = tab_bar,
161→        version_footer = version_footer,
162→    )
163→}
