456→    /// Process a single step of the event loop
457→    ///
458→    /// Fires due timers and tries to receive one command.
459→    /// Returns StepResult indicating what happened.
460→    pub fn step(&mut self) -> StepResult {
461→        // Fire any due timers
462→        self.fire_due_timers();
463→
464→        // Try to receive one command (non-blocking)
465→        match self.cmd_rx.try_recv() {
466→            Ok(cmd) => {
467→                let should_exit = self.handle_command(cmd);
468→                self.flush_mutations();
469→                if should_exit {
470→                    StepResult::Shutdown
471→                } else {
472→                    StepResult::Processed
473→                }
474→            }
475→            Err(tokio::sync::mpsc::error::TryRecvError::Empty) => StepResult::Idle,
476→            Err(tokio::sync::mpsc::error::TryRecvError::Disconnected) => StepResult::Shutdown,
477→        }
478→    }
