242→    /// Process pending UI mutations (called from timer or event loop)
243→    ///
244→    /// **Pattern**: Non-blocking drain of ui_rx channel
245→    /// **Frequency**: Call this in Slint timer (e.g., every 100ms)
246→    pub fn process_ui_mutations(&mut self) -> Result<(), Box<dyn std::error::Error>> {
247→        let mut mutation_count = 0;
248→        let mut error_count = 0;
249→
250→        // Drain all pending mutations (non-blocking)
251→        while let Ok(mutation) = self.ui_rx.try_recv() {
252→            // Apply property updates (continue on error to process remaining)
253→            for prop in mutation.properties {
254→                if let Err(e) = self.apply_property_update(prop) {
255→                    tracing::warn!(
256→                        page_id = %self.page_id,
257→                        error = %e,
258→                        "Property update failed"
259→                    );
260→                    error_count += 1;
261→                }
262→            }
263→
264→            // Apply VecModel operations (continue on error to process remaining)
265→            for op in mutation.model_ops {
266→                if let Err(e) = self.apply_vecmodel_op(op) {
267→                    tracing::warn!(
268→                        page_id = %self.page_id,
269→                        error = %e,
270→                        "VecModel operation failed"
271→                    );
272→                    error_count += 1;
273→                }
274→            }
275→
276→            mutation_count += 1;
277→        }
278→
279→        if mutation_count > 0 {
280→            tracing::debug!(
281→                page_id = %self.page_id,
282→                count = mutation_count,
283→                errors = error_count,
284→                "Processed UI mutations"
285→            );
286→        }
287→
288→        Ok(())
289→    }
