 1→//! Initialization and setup functions
 2→//!
 3→//! Handles Butler, transport, and P2P initialization.
 4→
 5→use std::sync::Arc;
 6→use butler::{Butler, SyncEvent};
 7→use courier::{Courier, CourierEvent, CourierHandle, CourierMode, HandshakeServices, Transport, TransportConfig};
 8→
 9→/// Initialize P2P after login (matches Tauri pattern)
10→///
11→/// **Context**: Called after Butler identity is set
12→/// **sync_rx**: Receiver for sync events (EnsureSync) - created in main.rs, sender passed to Butler
13→/// **capture_tx**: Optional broadcast channel for event capture (from CaptureHandle)
14→/// **Returns**: (CourierHandle, event receiver) for P2P operations
15→pub async fn init_p2p(
16→    butler: Arc<Butler>,
17→    mut sync_rx: tokio::sync::mpsc::Receiver<SyncEvent>,
18→    capture_tx: Option<tokio::sync::broadcast::Sender<String>>,
19→) -> Result<(CourierHandle, tokio::sync::mpsc::Receiver<CourierEvent>), String> {
20→    // Get device key from Butler (requires identity)
21→    let device_key = butler
22→        .device_key()
23→        .await
24→        .map_err(|e| format!("Failed to get device key: {}", e))?;
25→
26→    tracing::info!("Initializing transport with device key...");
27→
28→    // Initialize Transport
29→    let config = TransportConfig::new(device_key);
30→    let (transport, transport_rx) = Transport::init(config)
31→        .await
32→        .map_err(|e| format!("Failed to initialize transport: {}", e))?;
33→
34→    let transport = Arc::new(transport);
35→    let node_id = transport.node_id();
36→    tracing::info!(node_id = %node_id, "Transport initialized");
37→
38→    // Create HandshakeServices with Butler
39→    let handshake_services = Arc::new(HandshakeServices::new(butler.clone()));
40→
41→    // Initialize Courier with services and optional capture
42→    let (handle, event_rx, courier) =
43→        Courier::init_with_services_and_capture(CourierMode::User, transport, Some(handshake_services), capture_tx);
44→
45→    // Spawn courier event loop
46→    tokio::spawn(async move {
47→        courier.run(transport_rx).await;
48→    });
49→
50→    // Forward sync events to Coordinator (Scribe -> Butler -> Coordinator)
51→    // This enables EnsureSync to trigger connections/subscriptions
52→    let handle_for_sync = handle.clone();
53→    tokio::spawn(async move {
54→        while let Some(event) = sync_rx.recv().await {
55→            match event {
56→                SyncEvent::EnsureSync { user_did } => {
57→                    tracing::info!(user_did = %user_did, "Received EnsureSync from Scribe, forwarding to Coordinator");
58→                    if let Err(e) = handle_for_sync.ensure_sync(&user_did) {
59→                        tracing::warn!(user_did = %user_did, error = %e, "Failed to forward EnsureSync");
60→                    } else {
61→                        tracing::info!(user_did = %user_did, "Forwarded EnsureSync to Coordinator");
62→                    }
63→                }
64→                SyncEvent::SubscribeLayers { page_id, creator_did, layers } => {
65→                    tracing::info!(
66→                        page_id = %page_id,
67→                        creator_did = %creator_did,
68→                        count = layers.len(),
69→                        "Received SubscribeLayers from Scribe, forwarding to Coordinator"
70→                    );
71→                    if let Err(e) = handle_for_sync.subscribe_layers(&page_id, &creator_did, layers) {
72→                        tracing::warn!(error = %e, "Failed to forward SubscribeLayers");
73→                    }
74→                }
75→            }
76→        }
77→    });
78→
79→    Ok((handle, event_rx))
80→}
