  1→//! Slint Runtime - UI layer on main thread
  2→//!
  3→//! Owns: ComponentInstance, VecModels
  4→//! Receives: UiMutation from Lua thread
  5→//! Applies: VecModel operations via AppAPI global
  6→//!
  7→//! **Threading**: Must stay on main thread (Rc<ComponentInstance>, Rc<VecModel>)
  8→//! **Pattern**: Pull mutations from channel via process_ui_mutations()
  9→//! **Global API**: Uses `set_global_property` and `set_global_callback` for AppAPI
 10→
 11→use slint::{VecModel, Model};
 12→use slint_interpreter::{ComponentInstance, Compiler, Value as SlintValue};
 13→use std::rc::Rc;
 14→use std::collections::HashMap;
 15→use std::path::PathBuf;
 16→use tokio::sync::mpsc;
 17→use lua_runtime::{UiMutation, VecModelOp, PropertyUpdate, UiQuery, LuaCommand};
 18→
 19→/// Request to open native file picker for asset upload
 20→///
 21→/// **Context**: Triggered by Slint button click via `pick_asset_file` callback
 22→/// **Security**: Only user-initiated UI actions can trigger this
 23→#[derive(Debug)]
 24→pub struct AssetPickRequest {
 25→    /// Filter type: "images" for image files, "all" for all files
 26→    pub filter: String,
 27→}
 28→
 29→/// Global API name - apps define their public interface via `export global AppAPI`
 30→const GLOBAL_API_NAME: &str = "AppAPI";
 31→
 32→/// Slint runtime state (main thread only)
 33→///
 34→/// **Ownership**: Rc-based (NOT Send), stays on Slint event loop thread
 35→/// **Lifetime**: Lives until app window closes
 36→pub struct SlintRuntime {
 37→    /// App/Page identifier
 38→    pub page_id: String,
 39→
 40→    /// Slint component instance (UI window)
 41→    slint_instance: Rc<ComponentInstance>,
 42→
 43→    /// VecModels by property name in AppAPI global (e.g., "products", "orders")
 44→    global_models: HashMap<String, Rc<VecModel<SlintValue>>>,
 45→
 46→    /// Channel to receive UI mutations from Lua thread
 47→    ui_rx: mpsc::Receiver<UiMutation>,
 48→
 49→    /// Channel to receive UI queries from Lua thread (for ui:get)
 50→    query_rx: mpsc::Receiver<UiQuery>,
 51→
 52→    /// Channel to send commands to Lua thread
 53→    lua_tx: mpsc::Sender<LuaCommand>,
 54→
 55→    /// Channel to send tab switch requests (std::sync for Slint callback)
 56→    tab_switch_tx: Option<std::sync::mpsc::Sender<String>>,
 57→
 58→    /// Channel to send asset pick requests (std::sync for Slint callback)
 59→    asset_pick_tx: Option<std::sync::mpsc::Sender<AssetPickRequest>>,
 60→}
 61→
 62→impl SlintRuntime {
 63→    /// Load Slint UI from file and create runtime
 64→    ///
 65→    /// **Parameters**:
 66→    /// - `slint_path`: Path to .slint file
 67→    /// - `page_id`: App/page identifier
 68→    /// - `ui_rx`: Channel to receive UI mutations from Lua
 69→    /// - `query_rx`: Channel to receive UI queries from Lua (for ui:get)
 70→    /// - `lua_tx`: Channel to send commands to Lua
 71→    ///
 72→    /// **Returns**: SlintRuntime ready to process mutations
 73→    pub fn load(
 74→        slint_path: PathBuf,
 75→        page_id: String,
 76→        ui_rx: mpsc::Receiver<UiMutation>,
 77→        query_rx: mpsc::Receiver<UiQuery>,
 78→        lua_tx: mpsc::Sender<LuaCommand>,
 79→    ) -> Result<Self, Box<dyn std::error::Error>> {
 80→        tracing::info!(
 81→            page_id = %page_id,
 82→            path = %slint_path.display(),
 83→            "Loading Slint UI"
 84→        );
 85→
 86→        // Compile Slint component
 87→        let compiler = Compiler::default();
 88→
 89→        // Note: This is running on the main thread (not Tokio)
 90→        // We need to block on the async compilation
 91→        let result = match tokio::runtime::Handle::try_current() {
 92→            Ok(handle) => {
 93→                tokio::task::block_in_place(|| {
 94→                    handle.block_on(compiler.build_from_path(&slint_path))
 95→                })
 96→            }
 97→            Err(_) => {
 98→                // No runtime, create a temporary one
 99→                let rt = tokio::runtime::Runtime::new()
100→                    .map_err(|e| format!("Failed to create runtime: {}", e))?;
101→                rt.block_on(compiler.build_from_path(&slint_path))
102→            }
103→        };
104→
105→        // Check for compilation errors
106→        let diagnostics: Vec<_> = result
107→            .diagnostics()
108→            .filter(|d| d.level() == slint_interpreter::DiagnosticLevel::Error)
109→            .collect();
110→        if !diagnostics.is_empty() {
111→            let errors: Vec<String> = diagnostics.iter().map(|d| d.to_string()).collect();
112→            return Err(format!("Slint compilation errors: {}", errors.join("; ")).into());
113→        }
114→
115→        // Get the component definition (use default component name)
116→        let definition = result
117→            .component("App")
118→            .or_else(|| {
119→                // Try to get the first component if "App" doesn't exist
120→                result.component_names().next().and_then(|name| result.component(&name))
121→            })
122→            .ok_or_else(|| "No component found in .slint file")?;
123→
124→        // Create component instance
125→        let slint_instance = definition.create()
126→            .map_err(|e| format!("Failed to create instance: {:?}", e))?;
127→
128→        tracing::debug!(
129→            page_id = %page_id,
130→            "Slint component instance created"
131→        );
132→
133→        // Initialize models HashMap
134→        let global_models = HashMap::new();
135→
136→        let runtime = Self {
137→            page_id,
138→            slint_instance: Rc::new(slint_instance),
139→            global_models,
140→            ui_rx,
141→            query_rx,
142→            lua_tx,
143→            tab_switch_tx: None,
144→            asset_pick_tx: None,
145→        };
146→
147→        // Models are initialized via init_models() after load, passing manifest.models
148→        // This allows apps to declare their models in manifest.json
149→
150→        Ok(runtime)
151→    }
152→
153→    /// Initialize VecModels for array properties declared in manifest
154→    ///
155→    /// **Called by**: App loader after parsing manifest.json
156→    /// **Pattern**: Pre-create VecModels for declared models to enable incremental updates
157→    pub fn init_models(&mut self, model_names: &[String]) -> Result<(), Box<dyn std::error::Error>> {
158→        for model_name in model_names {
159→            if let Some(_model) = self.get_or_create_model(model_name) {
160→                tracing::info!(
161→                    page_id = %self.page_id,
162→                    model = %model_name,
163→                    "VecModel initialized from manifest"
164→                );
165→            } else {
166→                tracing::warn!(
167→                    page_id = %self.page_id,
168→                    model = %model_name,
169→                    "Model declared in manifest but not found in AppAPI"
170→                );
171→            }
172→        }
173→        Ok(())
174→    }
175→
176→    /// Get reference to Slint instance (for showing window, etc.)
177→    pub fn slint_instance(&self) -> &Rc<ComponentInstance> {
178→        &self.slint_instance
179→    }
180→
181→    /// Set the channel for tab switch requests
182→    ///
183→    /// **Context**: Called from app management to receive tab switch events
184→    pub fn set_tab_switch_channel(&mut self, tx: std::sync::mpsc::Sender<String>) {
185→        self.tab_switch_tx = Some(tx);
186→    }
187→
188→    /// Set the channel for asset pick requests
189→    ///
190→    /// **Context**: Called from app management to receive asset upload requests
191→    /// **Security**: Channel is triggered by Slint button click (user-initiated)
192→    pub fn set_asset_pick_channel(&mut self, tx: std::sync::mpsc::Sender<AssetPickRequest>) {
193→        self.asset_pick_tx = Some(tx);
194→    }
