196→    /// Get or create a VecModel for a property
197→    ///
198→    /// **Pattern**: Dynamically create VecModels when needed
199→    pub fn get_or_create_model(&mut self, prop_name: &str) -> Option<Rc<VecModel<SlintValue>>> {
200→        // Return existing model if we have it
201→        if let Some(model) = self.global_models.get(prop_name) {
202→            return Some(model.clone());
203→        }
204→
205→        // Check if this property exists and is a Model type
206→        if let Ok(value) = self.slint_instance.get_global_property(GLOBAL_API_NAME, prop_name) {
207→            if matches!(value, SlintValue::Model(_)) {
208→                // Create new VecModel
209→                let model = Rc::new(VecModel::<SlintValue>::default());
210→
211→                // Set as global property
212→                if let Err(e) = self.slint_instance.set_global_property(
213→                    GLOBAL_API_NAME,
214→                    prop_name,
215→                    SlintValue::Model(model.clone().into())
216→                ) {
217→                    tracing::warn!(
218→                        page_id = %self.page_id,
219→                        global = GLOBAL_API_NAME,
220→                        property = prop_name,
221→                        error = %e,
222→                        "Failed to set global model property"
223→                    );
224→                    return None;
225→                }
226→
227→                // Store and return
228→                self.global_models.insert(prop_name.to_string(), model.clone());
229→                tracing::info!(
230→                    page_id = %self.page_id,
231→                    global = GLOBAL_API_NAME,
232→                    property = prop_name,
233→                    "VecModel created on-demand"
234→                );
235→                return Some(model);
236→            }
237→        }
238→
239→        None
240→    }
241→
242→    /// Process pending UI mutations (called from timer or event loop)
243→    ///
244→    /// **Pattern**: Non-blocking drain of ui_rx channel
245→    /// **Frequency**: Call this in Slint timer (e.g., every 100ms)
246→    pub fn process_ui_mutations(&mut self) -> Result<(), Box<dyn std::error::Error>> {
247→        let mut mutation_count = 0;
248→        let mut error_count = 0;
249→
250→        // Drain all pending mutations (non-blocking)
251→        while let Ok(mutation) = self.ui_rx.try_recv() {
252→            // Apply property updates (continue on error to process remaining)
253→            for prop in mutation.properties {
254→                if let Err(e) = self.apply_property_update(prop) {
255→                    tracing::warn!(
256→                        page_id = %self.page_id,
257→                        error = %e,
258→                        "Property update failed"
259→                    );
260→                    error_count += 1;
261→                }
262→            }
263→
264→            // Apply VecModel operations (continue on error to process remaining)
265→            for op in mutation.model_ops {
266→                if let Err(e) = self.apply_vecmodel_op(op) {
267→                    tracing::warn!(
268→                        page_id = %self.page_id,
269→                        error = %e,
270→                        "VecModel operation failed"
271→                    );
272→                    error_count += 1;
273→                }
274→            }
275→
276→            mutation_count += 1;
277→        }
278→
279→        if mutation_count > 0 {
280→            tracing::debug!(
281→                page_id = %self.page_id,
282→                count = mutation_count,
283→                errors = error_count,
284→                "Processed UI mutations"
285→            );
286→        }
287→
288→        Ok(())
289→    }
290→
291→    /// Process pending UI queries (called from timer or event loop)
292→    ///
293→    /// **Pattern**: Non-blocking drain of query_rx channel
294→    /// **Frequency**: Call this in Slint timer alongside process_ui_mutations
295→    pub fn process_ui_queries(&mut self) {
296→        // Drain all pending queries (non-blocking)
297→        while let Ok(query) = self.query_rx.try_recv() {
298→            let result = self.read_property(&query.prop_name);
299→            // Send response back to Lua thread (ignore send errors - Lua may have timed out)
300→            let _ = query.response_tx.send(result);
301→        }
302→    }
303→
304→    /// Read a property from AppAPI global and convert to JSON
305→    fn read_property(&self, prop_name: &str) -> Option<serde_json::Value> {
306→        match self.slint_instance.get_global_property(GLOBAL_API_NAME, prop_name) {
307→            Ok(value) => Some(slint_value_to_json(&value)),
308→            Err(e) => {
309→                tracing::warn!(
310→                    page_id = %self.page_id,
311→                    global = GLOBAL_API_NAME,
312→                    property = %prop_name,
313→                    error = %e,
314→                    "Failed to read global property"
315→                );
316→                None
317→            }
318→        }
319→    }
