321→    /// Apply property update to AppAPI global
322→    ///
323→    /// **Pattern**: All app properties go through AppAPI global
324→    /// **Triggers**: Property change notification in Slint
325→    fn apply_property_update(&self, update: PropertyUpdate) -> Result<(), Box<dyn std::error::Error>> {
326→        let slint_val = json_to_slint_value(&update.value)?;
327→
328→        // All properties go to AppAPI global
329→        if let Err(e) = self.slint_instance.set_global_property(GLOBAL_API_NAME, &update.key, slint_val) {
330→            tracing::warn!(
331→                page_id = %self.page_id,
332→                global = GLOBAL_API_NAME,
333→                property = %update.key,
334→                error = %e,
335→                "Failed to set global property"
336→            );
337→            return Err(e.into());
338→        }
339→
340→        tracing::debug!(
341→            page_id = %self.page_id,
342→            global = GLOBAL_API_NAME,
343→            property = %update.key,
344→            "Global property updated"
345→        );
346→
347→        Ok(())
348→    }
349→
350→    /// Apply single VecModel operation to AppAPI global model
351→    ///
352→    /// **Triggers**: ModelNotify events (row_added, row_removed, row_changed)
353→    fn apply_vecmodel_op(&mut self, op: VecModelOp) -> Result<(), Box<dyn std::error::Error>> {
354→        use VecModelOp::*;
355→
356→        match op {
357→            Push { model_name, item } => {
358→                // Lazy model creation - create if not exists
359→                if !self.global_models.contains_key(&model_name) {
360→                    self.get_or_create_model(&model_name);
361→                }
362→                let model = match self.global_models.get(&model_name) {
363→                    Some(m) => m,
364→                    None => {
365→                        tracing::error!(
366→                            page_id = %self.page_id,
367→                            global = GLOBAL_API_NAME,
368→                            model = %model_name,
369→                            available_models = ?self.global_models.keys().collect::<Vec<_>>(),
370→                            "Model not found for Push operation (lazy creation failed)"
371→                        );
372→                        return Err(format!("Model not found in {}: {}", GLOBAL_API_NAME, model_name).into());
373→                    }
374→                };
375→                let slint_val = json_to_slint_value(&item)?;
376→                model.push(slint_val);
377→
378→                tracing::debug!(
379→                    page_id = %self.page_id,
380→                    global = GLOBAL_API_NAME,
381→                    model = %model_name,
382→                    row_count = model.row_count(),
383→                    "VecModel::push"
384→                );
385→            }
386→            Insert { model_name, index, item } => {
387→                // Lazy model creation - create if not exists
388→                if !self.global_models.contains_key(&model_name) {
389→                    self.get_or_create_model(&model_name);
390→                }
391→                let model = self.global_models.get(&model_name)
392→                    .ok_or_else(|| format!("Model not found in {}: {}", GLOBAL_API_NAME, model_name))?;
393→                let slint_val = json_to_slint_value(&item)?;
394→                model.insert(index, slint_val);
395→
396→                tracing::trace!(
397→                    page_id = %self.page_id,
398→                    global = GLOBAL_API_NAME,
399→                    model = %model_name,
400→                    index = index,
401→                    "VecModel::insert"
402→                );
403→            }
404→            Remove { model_name, index } => {
405→                if !self.global_models.contains_key(&model_name) {
406→                    self.get_or_create_model(&model_name);
407→                }
408→                let model = self.global_models.get(&model_name)
409→                    .ok_or_else(|| format!("Model not found in {}: {}", GLOBAL_API_NAME, model_name))?;
410→                if index < model.row_count() {
411→                    model.remove(index);
412→
413→                    tracing::trace!(
414→                        page_id = %self.page_id,
415→                        global = GLOBAL_API_NAME,
416→                        model = %model_name,
417→                        index = index,
418→                        "VecModel::remove"
419→                    );
420→                } else {
421→                    tracing::warn!(
422→                        page_id = %self.page_id,
423→                        global = GLOBAL_API_NAME,
424→                        model = %model_name,
425→                        index = index,
426→                        len = model.row_count(),
427→                        "Remove index out of bounds"
428→                    );
429→                }
430→            }
431→            Set { model_name, index, item } => {
432→                if !self.global_models.contains_key(&model_name) {
433→                    self.get_or_create_model(&model_name);
434→                }
435→                let model = self.global_models.get(&model_name)
436→                    .ok_or_else(|| format!("Model not found in {}: {}", GLOBAL_API_NAME, model_name))?;
437→                if index < model.row_count() {
438→                    let slint_val = json_to_slint_value(&item)?;
439→                    model.set_row_data(index, slint_val);
440→
441→                    tracing::trace!(
442→                        page_id = %self.page_id,
443→                        global = GLOBAL_API_NAME,
444→                        model = %model_name,
445→                        index = index,
446→                        "VecModel::set"
447→                    );
448→                } else {
449→                    tracing::warn!(
450→                        page_id = %self.page_id,
451→                        global = GLOBAL_API_NAME,
452→                        model = %model_name,
453→                        index = index,
454→                        len = model.row_count(),
455→                        "Set index out of bounds"
456→                    );
457→                }
458→            }
459→            Clear { model_name } => {
460→                // Lazy model creation - create if not exists
461→                if !self.global_models.contains_key(&model_name) {
462→                    self.get_or_create_model(&model_name);
463→                }
464→                let model = match self.global_models.get(&model_name) {
465→                    Some(m) => m,
466→                    None => {
467→                        tracing::error!(
468→                            page_id = %self.page_id,
469→                            global = GLOBAL_API_NAME,
470→                            model = %model_name,
471→                            available_models = ?self.global_models.keys().collect::<Vec<_>>(),
472→                            "Model not found for Clear operation (lazy creation failed)"
473→                        );
474→                        return Err(format!("Model not found in {}: {}", GLOBAL_API_NAME, model_name).into());
475→                    }
476→                };
477→                let count = model.row_count();
478→                model.set_vec(vec![]);
479→
480→                tracing::debug!(
481→                    page_id = %self.page_id,
482→                    global = GLOBAL_API_NAME,
483→                    model = %model_name,
484→                    removed = count,
485→                    "VecModel::clear"
486→                );
487→            }
488→            Replace { model_name, items } => {
489→                // Lazy model creation - create if not exists
490→                if !self.global_models.contains_key(&model_name) {
491→                    self.get_or_create_model(&model_name);
492→                }
493→                let model = match self.global_models.get(&model_name) {
494→                    Some(m) => m,
495→                    None => {
496→                        tracing::error!(
497→                            page_id = %self.page_id,
498→                            global = GLOBAL_API_NAME,
499→                            model = %model_name,
500→                            "Model not found for Replace operation"
501→                        );
502→                        return Err(format!("Model not found: {}", model_name).into());
503→                    }
504→                };
505→
506→                // Convert all items to Slint values
507→                let slint_items: Vec<SlintValue> = items
508→                    .into_iter()
509→                    .filter_map(|item| json_to_slint_value(&item).ok())
510→                    .collect();
511→
512→                let count = slint_items.len();
513→
514→                // Use set_vec for atomic replacement (single UI update)
515→                model.set_vec(slint_items);
516→
517→                tracing::debug!(
518→                    page_id = %self.page_id,
519→                    global = GLOBAL_API_NAME,
520→                    model = %model_name,
521→                    items = count,
522→                    "VecModel::replace (atomic)"
523→                );
524→            }
525→        }
526→
527→        Ok(())
528→    }
