530→    /// Setup shell-level callbacks (tab switching, add-app)
531→    ///
532→    /// **Pattern**: Wire shell callbacks to appropriate handlers
533→    /// **Special callbacks**:
534→    /// - `select-tab(name)` → sent to tab_switch_tx for tab switching
535→    /// - `add-app()` → could be wired to Lua if needed
536→    pub fn setup_callbacks(&self) -> Result<(), Box<dyn std::error::Error>> {
537→        let definition = self.slint_instance.definition();
538→
539→        let mut callback_count = 0;
540→        for callback_name in definition.callbacks() {
541→            // Handle select-tab specially - send to tab switch channel
542→            if callback_name == "select-tab" || callback_name == "select_tab" {
543→                if let Some(ref tx) = self.tab_switch_tx {
544→                    let tx = tx.clone();
545→                    self.slint_instance.set_callback(&callback_name, move |args| {
546→                        if let Some(tab_name) = args.first() {
547→                            if let SlintValue::String(name) = tab_name {
548→                                tracing::info!(
549→                                    tab = %name,
550→                                    "Tab switch requested"
551→                                );
552→                                let _ = tx.send(name.to_string());
553→                            }
554→                        }
555→                        SlintValue::Void
556→                    })?;
557→                    callback_count += 1;
558→                }
559→            }
560→            // add-app callback - currently no-op, could wire to Lua
561→        }
562→
563→        tracing::debug!(
564→            page_id = %self.page_id,
565→            callback_count = callback_count,
566→            "Shell callbacks configured"
567→        );
568→
569→        Ok(())
570→    }
571→
572→    /// Setup AppAPI global callbacks (generic Event Bus callbacks)
573→    ///
574→    /// **Pattern**: Wire AppAPI global callbacks to Lua
575→    /// Slint `AppAPI.callback foo(args)` → Lua `foo(args)`
576→    ///
577→    /// Only wires 3 generic callbacks - apps use Event Bus pattern:
578→    /// - on_click(target) - button clicks, selections
579→    /// - on_field_changed(field, value) - text input changes
580→    /// - on_modal_action(modal, action) - modal open/close/submit
581→    pub fn setup_global_callbacks(&self) -> Result<(), Box<dyn std::error::Error>> {
582→        // Generic Event Bus callbacks - same for ALL apps
583→        // Apps define these in their AppAPI and call them from UI elements
584→        let generic_callbacks = [
585→            "on_click",
586→            "on_field_changed",
587→            "on_modal_action",
588→            "on_pointer_event",  // For canvas/drawing apps that need x,y coordinates
589→            "on_scroll",         // For canvas/drawing apps that need scroll/zoom
590→            "on_hover",          // For cursor sync without drag (timer-based polling)
591→            "on_key_pressed",    // For games/interactive apps that need keyboard input
592→            "on_submit",         // For form submissions (chat, search, etc.)
593→            "on_text_input",     // For text input changes (typing indicators, etc.)
594→        ];
595→
596→        let mut callback_count = 0;
597→        for callback_name in generic_callbacks {
598→            let lua_tx = self.lua_tx.clone();
599→            let callback_name_owned = callback_name.to_string();
600→
601→            // Try to set the global callback - if it doesn't exist, that's OK (not all apps have all callbacks)
602→            match self.slint_instance.set_global_callback(GLOBAL_API_NAME, callback_name, move |args| {
603→                // Convert Slint args to JSON for Lua
604→                let json_args: Vec<serde_json::Value> = args
605→                    .iter()
606→                    .map(slint_value_to_json)
607→                    .collect();
608→
609→                tracing::trace!(
610→                    global = GLOBAL_API_NAME,
611→                    callback = %callback_name_owned,
612→                    arg_count = json_args.len(),
613→                    "AppAPI callback triggered"
614→                );
615→
616→                let _ = lua_tx.try_send(LuaCommand::UiCallback {
617→                    callback_name: callback_name_owned.clone(),
618→                    args: json_args,
619→                });
620→                SlintValue::Void
621→            }) {
622→                Ok(_) => {
623→                    callback_count += 1;
624→                    tracing::debug!(
625→                        page_id = %self.page_id,
626→                        global = GLOBAL_API_NAME,
627→                        callback = callback_name,
628→                        "AppAPI callback configured"
629→                    );
630→                }
631→                Err(e) => {
632→                    // Log at warn level to debug callback registration issues
633→                    tracing::warn!(
634→                        page_id = %self.page_id,
635→                        global = GLOBAL_API_NAME,
636→                        callback = callback_name,
637→                        error = %e,
638→                        "AppAPI callback registration failed"
639→                    );
640→                }
641→            }
642→        }
643→
644→        tracing::info!(
645→            page_id = %self.page_id,
646→            global = GLOBAL_API_NAME,
647→            callback_count = callback_count,
648→            "AppAPI callbacks configured"
649→        );
650→
651→        // Asset file picker callback - triggers native file dialog
652→        // This requires a user click in Slint (security: user-initiated only)
653→        if let Some(ref tx) = self.asset_pick_tx {
654→            let tx = tx.clone();
655→            let page_id = self.page_id.clone();
656→            match self.slint_instance.set_global_callback(GLOBAL_API_NAME, "pick_asset_file", move |args| {
657→                let filter = args.first()
658→                    .and_then(|v| v.clone().try_into().ok())
659→                    .and_then(|v: slint::SharedString| Some(v.to_string()))
660→                    .unwrap_or_else(|| "all".to_string());
661→
662→                tracing::info!(
663→                    page_id = %page_id,
664→                    filter = %filter,
665→                    "Asset pick requested via AppAPI callback"
666→                );
667→
668→                let _ = tx.send(AssetPickRequest { filter });
669→                SlintValue::Void
670→            }) {
671→                Ok(_) => {
672→                    tracing::debug!(
673→                        page_id = %self.page_id,
674→                        global = GLOBAL_API_NAME,
675→                        callback = "pick_asset_file",
676→                        "Asset picker callback configured"
677→                    );
678→                }
679→                Err(e) => {
680→                    tracing::warn!(
681→                        page_id = %self.page_id,
682→                        global = GLOBAL_API_NAME,
683→                        callback = "pick_asset_file",
684→                        error = %e,
685→                        "Asset picker callback registration failed (app may not define it)"
686→                    );
687→                }
688→            }
689→        }
690→
691→        Ok(())
692→    }
693→}
694→
695→/// Convert Slint value to JSON for passing to Lua
696→fn slint_value_to_json(value: &SlintValue) -> serde_json::Value {
697→    match value {
698→        SlintValue::String(s) => serde_json::Value::String(s.to_string()),
699→        SlintValue::Number(n) => serde_json::json!(n),
700→        SlintValue::Bool(b) => serde_json::Value::Bool(*b),
701→        SlintValue::Void => serde_json::Value::Null,
702→        SlintValue::Image(_) => serde_json::Value::Null, // Can't serialize images
703→        SlintValue::Model(_) => serde_json::Value::Null, // Can't serialize models
704→        SlintValue::Struct(s) => {
705→            // Convert struct fields to JSON object
706→            let obj: serde_json::Map<String, serde_json::Value> = s
707→                .iter()
708→                .map(|(k, v)| (k.to_string(), slint_value_to_json(&v)))
709→                .collect();
710→            serde_json::Value::Object(obj)
711→        }
712→        SlintValue::Brush(_) => serde_json::Value::Null, // Can't serialize brushes
713→        _ => serde_json::Value::Null,
714→    }
715→}
716→
717→/// Convert JSON to Slint value
718→///
719→/// **Note**: This is similar to lua_to_slint_value in slint_model_bindings.rs
720→fn json_to_slint_value(value: &serde_json::Value) -> Result<SlintValue, Box<dyn std::error::Error>> {
721→    use slint_interpreter::Value;
722→
723→    match value {
724→        serde_json::Value::Null => Ok(Value::Void),
725→        serde_json::Value::Bool(b) => Ok(Value::Bool(*b)),
726→        serde_json::Value::Number(n) => {
727→            if let Some(f) = n.as_f64() {
728→                Ok(Value::Number(f))
729→            } else {
730→                Err(format!("Invalid number: {}", n).into())
731→            }
732→        }
733→        serde_json::Value::String(s) => {
734→            Ok(Value::String(slint::SharedString::from(s.as_str())))
735→        }
736→        serde_json::Value::Array(arr) => {
737→            // Convert as Slint Model
738→            let items: Result<Vec<_>, _> = arr.iter()
739→                .map(json_to_slint_value)
740→                .collect();
741→            let items = items?;
742→            Ok(Value::Model(Rc::new(VecModel::from(items)).into()))
743→        }
744→        serde_json::Value::Object(obj) => {
745→            // Convert as Slint Struct
746→            let fields: Result<Vec<_>, _> = obj.iter()
747→                .map(|(k, v)| {
748→                    json_to_slint_value(v).map(|val| (k.clone(), val))
749→                })
750→                .collect();
751→            let fields = fields?;
752→            Ok(Value::Struct(slint_interpreter::Struct::from_iter(fields).into()))
753→        }
754→    }
755→}
