114→
115→    let butler = Arc::new(Butler::new(store.clone(), layer_cache, asset_store, Some(sync_tx)));
116→
117→    // P2P state - initialized after login
118→    let courier_handle: Arc<RwLock<Option<CourierHandle>>> = Arc::new(RwLock::new(None));
119→
120→    // Start debug server if requested
121→    let mut ui_rx: Option<mpsc::Receiver<UiCommand>> = None;
