181→    #[cfg(feature = "profiling")]
182→    let capture_tx: Option<tokio::sync::broadcast::Sender<String>> = None;
183→
184→    // Register callbacks
185→
186→    // Auth callback: on login success, initialize P2P and event listener
187→    let butler_for_login = butler.clone();
188→    let courier_handle_for_login = courier_handle.clone();
189→    let sync_event_rx_for_login = sync_event_rx.clone();
190→    let shell_weak_for_login = shell.as_weak();
