232→    sthalam_shell::callbacks::auth::register(&shell, butler.clone(), on_login_success);
233→    sthalam_shell::callbacks::spaces::register(&shell, butler.clone());
234→    sthalam_shell::callbacks::pages::register(&shell, butler.clone());
235→    sthalam_shell::callbacks::nodes::register(
