  1→//! CourierEvent handling
  2→//!
  3→//! Spawns event listener for P2P events and updates UI accordingly.
  4→
  5→use std::collections::HashSet;
  6→use std::sync::Arc;
  7→
  8→use butler::Butler;
  9→use courier::CourierEvent;
 10→use sthalam_shell::Shell;
 11→use tokio::sync::mpsc::Receiver;
 12→
 13→/// Spawn event listener for courier events
 14→///
 15→/// Handles: PeerAuthenticated, ConnectionFailed, PeerDisconnected,
 16→/// SpacePublished, PublishFailed, ShareableLinkReceived,
 17→/// ViewerSpaceReceived, ViewerSyncComplete
 18→pub fn spawn_event_listener(
 19→    mut event_rx: Receiver<CourierEvent>,
 20→    shell_weak: slint::Weak<Shell>,
 21→    butler: Arc<Butler>,
 22→) {
 23→    tokio::spawn(async move {
 24→        while let Some(event) = event_rx.recv().await {
 25→            match event {
 26→                CourierEvent::PeerAuthenticated { node_id, username, .. } => {
 27→                    tracing::info!(username = %username, node_id = %node_id, "Peer authenticated");
 28→                    let shell_weak = shell_weak.clone();
 29→                    let butler = butler.clone();
 30→                    let node_id_str = node_id.clone();
 31→                    slint::invoke_from_event_loop(move || {
 32→                        if let Some(shell) = shell_weak.upgrade() {
 33→                            shell.set_connecting(false);
 34→                            shell.set_show_add_modal(false);
 35→                            shell.set_connection_string("".into());
 36→
 37→                            // Mark node as connected in storage
 38→                            let _ = butler.nodes().set_connected(&node_id_str, true);
 39→
 40→                            // Refresh nodes list
 41→                            let nodes = butler.nodes().list().unwrap_or_default();
 42→                            let node_infos: Vec<sthalam_shell::NodeInfo> = nodes
 43→                                .iter()
 44→                                .map(sthalam_shell::sovereign_node_to_node_info)
 45→                                .collect();
 46→                            shell.set_nodes(slint::ModelRc::new(slint::VecModel::from(node_infos)));
 47→
 48→                            shell.set_toast_message(format!("Connected to {}", username).into());
 49→                            shell.set_toast_is_error(false);
 50→                            shell.set_toast_visible(true);
 51→                        }
 52→                    })
 53→                    .ok();
 54→                }
 55→                CourierEvent::ConnectionFailed { node_id, error } => {
 56→                    tracing::warn!(node_id = %node_id, error = %error, "Connection failed");
 57→                    let shell_weak = shell_weak.clone();
 58→                    let err_msg = format!("Connection failed: {}", error);
 59→                    slint::invoke_from_event_loop(move || {
 60→                        if let Some(shell) = shell_weak.upgrade() {
 61→                            shell.set_connecting(false);
 62→                            shell.set_connecting_website(false);
 63→                            shell.set_error_message(err_msg.clone().into());
 64→                            shell.set_toast_message(err_msg.into());
 65→                            shell.set_toast_is_error(true);
 66→                            shell.set_toast_visible(true);
 67→                        }
 68→                    })
 69→                    .ok();
 70→                }
 71→                CourierEvent::PeerDisconnected { node_id } => {
 72→                    tracing::info!(node_id = %node_id, "Peer disconnected");
 73→                    let shell_weak = shell_weak.clone();
 74→                    let butler = butler.clone();
 75→                    let node_id_str = node_id.clone();
 76→                    slint::invoke_from_event_loop(move || {
 77→                        if let Some(shell) = shell_weak.upgrade() {
 78→                            let _ = butler.nodes().set_connected(&node_id_str, false);
 79→
 80→                            let nodes = butler.nodes().list().unwrap_or_default();
 81→                            let node_infos: Vec<sthalam_shell::NodeInfo> = nodes
 82→                                .iter()
 83→                                .map(sthalam_shell::sovereign_node_to_node_info)
 84→                                .collect();
 85→                            shell.set_nodes(slint::ModelRc::new(slint::VecModel::from(node_infos)));
 86→                        }
 87→                    })
 88→                    .ok();
 89→                }
 90→                CourierEvent::SpacePublished { node_id, space_id } => {
 91→                    tracing::info!(space_id = %space_id, node_id = %node_id, "Space published");
 92→                    let shell_weak = shell_weak.clone();
 93→                    let butler = butler.clone();
 94→                    let published_space_id = space_id.clone();
 95→                    slint::invoke_from_event_loop(move || {
 96→                        if let Some(shell) = shell_weak.upgrade() {
 97→                            shell.set_publishing(false);
 98→                            shell.set_toast_message("Space published successfully".into());
 99→                            shell.set_toast_is_error(false);
100→                            shell.set_toast_visible(true);
101→
102→                            // Refresh connected-nodes list with updated published state
103→                            let current_space_id = shell.get_current_space_id().to_string();
104→                            if current_space_id == published_space_id {
105→                                let published_node_dids: HashSet<String> = butler
106→                                    .publish().get_nodes_with_permits(&current_space_id)
107→                                    .unwrap_or_default()
108→                                    .into_iter()
109→                                    .collect();
110→
111→                                let nodes = butler.nodes().list().unwrap_or_default();
112→                                let connected_nodes: Vec<sthalam_shell::NodeInfo> = nodes
113→                                    .iter()
114→                                    .filter(|n| n.is_connected)
115→                                    .map(|n| sthalam_shell::sovereign_node_to_node_info_with_published(n, &published_node_dids))
116→                                    .collect();
117→                                shell.set_connected_nodes(slint::ModelRc::new(slint::VecModel::from(connected_nodes)));
118→                            }
119→                        }
120→                    })
121→                    .ok();
122→                }
123→                CourierEvent::PublishFailed { error, .. } => {
124→                    tracing::warn!(error = %error, "Publish failed");
125→                    let shell_weak = shell_weak.clone();
126→                    let err_msg = format!("Publish failed: {}", error);
127→                    slint::invoke_from_event_loop(move || {
128→                        if let Some(shell) = shell_weak.upgrade() {
129→                            shell.set_publishing(false);
130→                            shell.set_toast_message(err_msg.into());
131→                            shell.set_toast_is_error(true);
132→                            shell.set_toast_visible(true);
133→                        }
134→                    })
135→                    .ok();
136→                }
137→                CourierEvent::ShareableLinkReceived { permit, .. } => {
138→                    tracing::info!("Received shareable link");
139→                    let shell_weak = shell_weak.clone();
140→                    slint::invoke_from_event_loop(move || {
141→                        if let Some(shell) = shell_weak.upgrade() {
142→                            shell.set_requesting_link(false);
143→                            shell.set_shareable_link(permit.into());
144→                        }
145→                    })
146→                    .ok();
147→                }
148→                CourierEvent::ViewerSpaceReceived { space, .. } => {
149→                    tracing::info!(space_name = %space.name, "Viewer received space");
150→                    let shell_weak = shell_weak.clone();
151→                    let space_name = space.name.clone();
152→                    slint::invoke_from_event_loop(move || {
153→                        if let Some(shell) = shell_weak.upgrade() {
154→                            shell.set_toast_message(format!("Receiving: {}", space_name).into());
155→                            shell.set_toast_is_error(false);
156→                            shell.set_toast_visible(true);
157→                        }
158→                    })
159→                    .ok();
160→                }
161→                CourierEvent::ViewerSyncComplete { pages_synced, .. } => {
162→                    tracing::info!(pages_synced = pages_synced, "Viewer sync complete");
163→                    let shell_weak = shell_weak.clone();
164→                    let butler = butler.clone();
165→                    slint::invoke_from_event_loop(move || {
166→                        if let Some(shell) = shell_weak.upgrade() {
167→                            shell.set_connecting_website(false);
168→                            shell.set_show_add_website_modal(false);
169→
170→                            // Refresh spaces list
171→                            let spaces = butler.spaces().list().unwrap_or_default();
172→                            let space_infos: Vec<sthalam_shell::SpaceInfo> = spaces
173→                                .iter()
174→                                .map(|s| sthalam_shell::SpaceInfo {
175→                                    id: s.id.clone().into(),
176→                                    name: s.name.clone().into(),
177→                                    app_count: 0,
178→                                })
179→                                .collect();
180→                            shell.set_spaces(slint::ModelRc::new(slint::VecModel::from(space_infos)));
181→
182→                            shell.set_toast_message(format!("Synced {} pages", pages_synced).into());
183→                            shell.set_toast_is_error(false);
184→                            shell.set_toast_visible(true);
185→                        }
186→                    })
187→                    .ok();
188→                }
189→                _ => {} // Ignore other events
190→            }
191→        }
192→    });
193→}
